// Normalise a telemetry event and estimate cost.
// Prices in Pricing Config are PLACEHOLDERS. Local models = 0 marginal token cost. Use your provider's current price list.
const prices = JSON.parse($input.first().json.price_per_1k_tokens_json);
const b = $input.first().json.body || {};
const model = String(b.model || 'unknown').slice(0, 64);
const pin = Math.max(0, parseInt(b.prompt_tokens, 10) || 0);
const pout = Math.max(0, parseInt(b.completion_tokens, 10) || 0);
const p = prices[model] || { in: 0, out: 0 };
const cost = (pin / 1000) * p.in + (pout / 1000) * p.out;
const fb = [1, -1, 0].includes(Number(b.user_feedback)) ? Number(b.user_feedback) : null;
return [{ json: {
  workflow: String(b.workflow || 'unknown').slice(0, 128),
  execution_id: String(b.execution_id || '').slice(0, 64),
  model, prompt_tokens: pin, completion_tokens: pout,
  latency_ms: Math.max(0, parseInt(b.latency_ms, 10) || 0),
  est_cost_usd: Math.round(cost * 1e6) / 1e6,
  status: ['ok', 'error', 'blocked'].includes(b.status) ? b.status : 'ok',
  user_feedback: fb
} }];

// Thresholds - agree these with the customer as part of POC success criteria.
const t = { max_error_rate: 0.05, max_p95_latency_ms: 15000, max_hourly_cost_usd: 5 };
const m = $input.first().json;
const breaches = [];
if (Number(m.error_rate) > t.max_error_rate) breaches.push(`error rate ${m.error_rate} > ${t.max_error_rate}`);
if (Number(m.p95_latency_ms) > t.max_p95_latency_ms) breaches.push(`p95 latency ${m.p95_latency_ms} ms > ${t.max_p95_latency_ms} ms`);
if (Number(m.est_cost_usd) > t.max_hourly_cost_usd) breaches.push(`hourly cost ${m.est_cost_usd} USD > ${t.max_hourly_cost_usd} USD`);
return [{ json: { ...m, thresholds: t, breaches, alert: breaches.length > 0 } }];

